    @classmethod
    def dos_totais(cls, totais: Mapping[Destino, TotalDoDestino]) -> "ParteAutomatica":
        lista, fila = totais[Destino.LISTA_DE_BAIXA], totais[Destino.FILA_DE_EXCECOES]
