    def _da_lista(self, linha: LinhaDeDecisao, autoria: _Autoria) -> _Decisao:
        item = self._lista.get(linha.item)
        if item is None:
            raise _NaoAplicada(
                f"Item {linha.item}: não está na Lista de baixa da execução {self._execucao}; decisão ignorada."
